<template>
  <div
    class="compose-progress"
    :class="{ 'compose-progress-compact': compact }"
    role="status"
    aria-live="polite"
  >
    <div class="compose-organizer" aria-hidden="true">
      <span class="compose-source compose-source-one"></span>
      <span class="compose-source compose-source-two"></span>
      <span class="compose-source compose-source-three"></span>
      <span class="compose-thread compose-thread-one"></span>
      <span class="compose-thread compose-thread-two"></span>
      <span class="compose-thread compose-thread-three"></span>
      <span class="compose-line compose-line-one"></span>
      <span class="compose-line compose-line-two"></span>
      <span class="compose-line compose-line-three"></span>
    </div>

    <div class="compose-copy">
      <div class="compose-heading">
        <strong>Composing your <AiViewTerm /></strong>
        <span>{{ progressState.timeLabel }}</span>
      </div>
      <p>{{ progressState.stage }}</p>
      <div
        class="compose-track"
        role="progressbar"
        :aria-valuenow="progressState.percent"
        aria-valuemin="0"
        aria-valuemax="100"
        :aria-label="`${progressState.stage}. ${progressState.timeLabel}.`"
      >
        <span :style="{ transform: `scaleX(${progressState.progress})` }"></span>
      </div>
      <p v-if="!compact" class="compose-departure">
        <template v-if="surface === 'home'">You can keep exploring the site. Your <AiViewTerm /> will keep composing, and we&rsquo;ll let you know when it&rsquo;s ready.</template>
        <template v-else>You can close this panel. Your <AiViewTerm /> will keep composing, and we&rsquo;ll let you know when it&rsquo;s ready.</template>
      </p>
    </div>
  </div>
</template>

<script>
import AiViewTerm from '../ui/AiViewTerm.vue';
import { viewComposeProgress } from '../../utils/viewComposeProgress';

export default {
  name: 'ViewComposeProgress',
  components: { AiViewTerm },
  props: {
    surface: { type: String, default: 'panel' },
    startedAt: { type: Number, default: 0 },
    compact: { type: Boolean, default: false },
  },
  data() {
    return { now: Date.now(), timer: null };
  },
  computed: {
    progressState() {
      return viewComposeProgress(this.startedAt, this.now);
    },
  },
  mounted() {
    if (!this.compact) {
      window.dispatchEvent(new CustomEvent('site-view-progress-inline', { detail: { delta: 1 } }));
    }
    this.timer = window.setInterval(() => { this.now = Date.now(); }, 250);
  },
  beforeUnmount() {
    window.clearInterval(this.timer);
    if (!this.compact) {
      window.dispatchEvent(new CustomEvent('site-view-progress-inline', { detail: { delta: -1 } }));
    }
  },
};
</script>

